    16	export function formatSlot({ day, start, end }) {
    17	  const hm = (t) => `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`;
    18	  return `${day} ${hm(start)}-${hm(end)}`;
    19	}
    20	
    21	export function overlaps(a, b) {
    22	  return a.day === b.day && a.start < b.end && b.start < a.end;
