// Waitlist for slots that are already taken (#21). When a booking is cancelled, its slot is offered to the
// first person who waits for that room at an overlapping time. The offer holds for 30 minutes.
import { overlaps, parseSlot } from './slots.js';

export const OFFER_MINUTES = 30;

export function createWaitlist() {
  return { entries: [], seq: 1 };
}

// Join the waitlist. A person waits at most once for the same room and slot.
export function join(list, { person, room, slot }) {
  if (!person) throw new Error('person is required');
  const s = parseSlot(slot);
  const same = (e) => e.person === person && e.room === room && e.day === s.day && e.start === s.start && e.end === s.end;
  if (list.entries.some(same)) return { ok: false, reason: 'already waiting' };
  list.entries.push({ seq: list.seq++, person, room, ...s });
  return { ok: true, position: waitingFor(list, room, s).length };
}

// Leave the waitlist for a room. Returns whether the person was waiting.
export function leave(list, person, room) {
  const before = list.entries.length;
  list.entries = list.entries.filter((e) => !(e.person === person && e.room === room));
  return list.entries.length < before;
}

// Everyone waiting for the room at a time that overlaps the slot, first come first.
export function waitingFor(list, room, slot) {
  return list.entries.filter((e) => e.room === room && overlaps(e, slot)).sort((a, b) => a.seq - b.seq);
}

// A booking was cancelled: offer its slot to the first person waiting, and take that entry off the waitlist
// (the person joins again if they decline the offer).
export function offerFreedSlot(list, cancelled, now = Date.now()) {
  const [first] = waitingFor(list, cancelled.room, cancelled);
  if (!first) return null;
  list.entries = list.entries.filter((e) => e !== first);
  return {
    to: first.person,
    room: cancelled.room,
    day: cancelled.day,
    start: cancelled.start,
    end: cancelled.end,
    expiresAt: now + OFFER_MINUTES * 60_000,
  };
}

// How many people wait, per room.
export function countsByRoom(list) {
  const counts = {};
  for (const e of list.entries) counts[e.room] = (counts[e.room] ?? 0) + 1;
  return counts;
}

