import { parseSlot } from '../src/slots.js';
import { OFFER_MINUTES, countsByRoom, createWaitlist, join, leave, offerFreedSlot, waitingFor } from '../src/waitlist.js';

const NINE = '2026-03-04 09:00-10:00';
const HALF_PAST_NINE = '2026-03-04 09:30-10:30';
const ONE_PM = '2026-03-04 13:00-14:00';
const NEXT_DAY = '2026-03-05 09:00-10:00';

// A cancelled booking, the way `cancel` of bookings.js returns it.
const cancelled = (room, slot) => ({ id: 1, room, person: 'someone', ...parseSlot(slot) });

test('the first person to join waits in position 1', () => {
  const list = createWaitlist();
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 1 });
});

test('the position counts the people who wait for the same room at an overlapping time', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  assert.deepEqual(join(list, { person: 'ken', room: 'small', slot: HALF_PAST_NINE }), { ok: true, position: 2 });
  assert.deepEqual(join(list, { person: 'aya', room: 'small', slot: ONE_PM }), { ok: true, position: 1 });
  assert.deepEqual(join(list, { person: 'rin', room: 'small', slot: NEXT_DAY }), { ok: true, position: 1 });
  assert.deepEqual(join(list, { person: 'sho', room: 'large', slot: NINE }), { ok: true, position: 1 });
});

test('joining needs a person and a well written slot', () => {
  const list = createWaitlist();
  assert.throws(() => join(list, { room: 'small', slot: NINE }), /person is required/);
  assert.throws(() => join(list, { person: '', room: 'small', slot: NINE }), /person is required/);
  assert.throws(() => join(list, { person: 'mio', room: 'small', slot: 'tomorrow morning' }), /not a slot/);
  assert.deepEqual(list.entries, []);
});

test('a person waits at most once for the same room and slot', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: NINE }), { ok: false, reason: 'already waiting' });
  assert.equal(list.entries.length, 1);
});

test('the same person may wait for another room, another time, or another day', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  assert.equal(join(list, { person: 'mio', room: 'large', slot: NINE }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'small', slot: HALF_PAST_NINE }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-11:00' }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'small', slot: NEXT_DAY }).ok, true);
  assert.equal(join(list, { person: 'ken', room: 'small', slot: NINE }).ok, true);
  assert.equal(list.entries.length, 6);
});

test('leaving takes the person off the waitlist of that room only', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  join(list, { person: 'mio', room: 'small', slot: ONE_PM });
  join(list, { person: 'mio', room: 'large', slot: NINE });
  join(list, { person: 'ken', room: 'small', slot: NINE });
  assert.equal(leave(list, 'mio', 'small'), true);
  assert.deepEqual(
    list.entries.map((e) => [e.person, e.room]),
    [['mio', 'large'], ['ken', 'small']],
  );
});

test('leaving says when the person was not waiting', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  assert.equal(leave(list, 'ken', 'small'), false);
  assert.equal(leave(list, 'mio', 'large'), false);
  assert.equal(list.entries.length, 1);
  assert.equal(leave(list, 'mio', 'small'), true);
  assert.equal(leave(list, 'mio', 'small'), false);
});

test('the people waiting for a slot are listed first come first', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: HALF_PAST_NINE });
  join(list, { person: 'sho', room: 'large', slot: NINE });
  join(list, { person: 'aya', room: 'small', slot: ONE_PM });
  join(list, { person: 'ken', room: 'small', slot: NINE });
  join(list, { person: 'rin', room: 'small', slot: NEXT_DAY });
  list.entries.reverse(); // the order comes from when they joined, not from where the entries are kept
  assert.deepEqual(waitingFor(list, 'small', parseSlot(NINE)).map((e) => e.person), ['mio', 'ken']);
  assert.deepEqual(waitingFor(list, 'small', parseSlot('2026-03-04 10:30-11:00')), []);
});

test('a freed slot is offered to the first person waiting, for 30 minutes', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: HALF_PAST_NINE });
  join(list, { person: 'ken', room: 'small', slot: NINE });
  const now = Date.UTC(2026, 2, 3, 12, 0);
  assert.equal(OFFER_MINUTES, 30);
  assert.deepEqual(offerFreedSlot(list, cancelled('small', NINE), now), {
    to: 'mio',
    room: 'small',
    day: '2026-03-04',
    start: 540,
    end: 600,
    expiresAt: now + 30 * 60_000,
  });
});

test('the person who gets the offer comes off the waitlist, and the next freed slot goes to the next person', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  join(list, { person: 'mio', room: 'small', slot: ONE_PM });
  join(list, { person: 'ken', room: 'small', slot: NINE });
  assert.equal(offerFreedSlot(list, cancelled('small', NINE)).to, 'mio');
  // only the entry that got the offer is taken off: mio still waits for 13:00
  assert.deepEqual(
    list.entries.map((e) => [e.person, e.start]),
    [['mio', 780], ['ken', 540]],
  );
  assert.equal(offerFreedSlot(list, cancelled('small', NINE)).to, 'ken');
  assert.equal(offerFreedSlot(list, cancelled('small', NINE)), null);
  // the person joins again if they decline the offer
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: NINE }), { ok: true, position: 1 });
});

test('the offer runs from the present time when no time is given', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: NINE });
  const before = Date.now();
  const offer = offerFreedSlot(list, cancelled('small', NINE));
  const after = Date.now();
  assert.ok(offer.expiresAt >= before + 30 * 60_000);
  assert.ok(offer.expiresAt <= after + 30 * 60_000);
});

test('a freed slot is offered to nobody when nobody waits for it', () => {
  const list = createWaitlist();
  assert.equal(offerFreedSlot(list, cancelled('small', NINE)), null);
  join(list, { person: 'mio', room: 'large', slot: NINE });
  join(list, { person: 'ken', room: 'small', slot: ONE_PM });
  join(list, { person: 'aya', room: 'small', slot: NEXT_DAY });
  assert.equal(offerFreedSlot(list, cancelled('small', NINE)), null);
  assert.equal(list.entries.length, 3);
});

test('the people waiting are counted per room', () => {
  const list = createWaitlist();
  assert.deepEqual(countsByRoom(list), {});
  join(list, { person: 'mio', room: 'small', slot: NINE });
  join(list, { person: 'ken', room: 'small', slot: ONE_PM });
  join(list, { person: 'aya', room: 'large', slot: NINE });
  assert.deepEqual(countsByRoom(list), { small: 2, large: 1 });
  leave(list, 'aya', 'large');
  assert.deepEqual(countsByRoom(list), { small: 2 });
});

